import React, { useState } from "react";
import { View, Text } from "react-native";
import { SkeuoCheckbox } from "../skeuo-checkbox";
import { useSkeuo } from "../theme";
export function HabitList({ value, onValueChange }: {value?:string[];onValueChange?:(value:string[])=>void}) {
  const { colors: c } = useSkeuo();
  const [localDone, setLocalDone] = useState<string[]>(["A little movement"]);
  const done = value ?? localDone;
  const setDone = (next:string[]) => { setLocalDone(next); onValueChange?.(next); };
  const labels = [
    "A little movement",
    "Read ten pages",
    "Make something",
    "Get outside",
  ];
  return (
    <View style={{ gap: 12 }}>
      <Text
        accessibilityLiveRegion="polite"
        style={{ color: c.muted, fontSize: 12 }}
      >
        {done.length} of {labels.length} complete today
      </Text>
      {labels.map((label) => (
        <SkeuoCheckbox
          key={label}
          label={label}
          checked={done.includes(label)}
          onCheckedChange={(checked) =>
            setDone(checked ? [...done,label] : done.filter(item=>item!==label))
          }
        />
      ))}
    </View>
  );
}

import { StyleSheet, Text, View } from "react-native";
import * as Checkbox from "@rn-primitives/checkbox";
import { useSkeuo, useFeedback } from "./theme";
import { styles } from "./styles";
import type { ToggleProps } from "./types";
import { SkeuoText } from "./skeuo-text";
export function SkeuoCheckbox({
  label,
  checked,
  onCheckedChange,
  disabled,
}: ToggleProps) {
  const { colors } = useSkeuo();
  const feedback = useFeedback();
  return (
    <Checkbox.Root
      accessibilityLabel={label}
      checked={checked}
      disabled={disabled}
      onCheckedChange={(v) => {
        feedback();
        onCheckedChange(v);
      }}
      style={StyleSheet.flatten([
        styles.row,
        styles.touch,
        { opacity: disabled ? 0.45 : 1 },
      ])}
    >
      <View
        style={[
          styles.check,
          {
            backgroundColor: checked ? colors.accent : colors.well,
            borderColor: colors.edge,
          },
        ]}
      >
        <Checkbox.Indicator>
          <Text style={{ color: colors.accentInk, fontWeight: "700" }}>✓</Text>
        </Checkbox.Indicator>
      </View>
      <View style={styles.label}>
        <SkeuoText>{label}</SkeuoText>
      </View>
    </Checkbox.Root>
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}

import React from "react";
export type ButtonProps = {
  children: React.ReactNode;
  onPress: () => void;
  disabled?: boolean;
  variant?: "default" | "accent";
  accessibilityLabel?: string;
};
export type ToggleProps = {
  label: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  disabled?: boolean;
};
export type OptionsProps = {
  label: string;
  value: string;
  onValueChange: (value: string) => void;
  options: { label: string; value: string; disabled?: boolean }[];
};
export type OverlayProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  children: React.ReactNode;
};

import React from "react";
import { Text } from "react-native";
import { useSkeuo } from "./theme";
export function SkeuoText({
  children,
  muted = false,
}: {
  children: React.ReactNode;
  muted?: boolean;
}) {
  const { colors } = useSkeuo();
  return (
    <Text
      style={{
        color: muted ? colors.muted : colors.ink,
        fontSize: 16,
        lineHeight: 24,
      }}
    >
      {children}
    </Text>
  );
}
